<?php
function getFirstKChars($s, $k) {
    // Ensure $k does not exceed the length of the string
    if ($k > strlen($s)) {
        return $s; // Return the entire string if $k is greater than the string length
    }

    // Return the first $k characters of the string
    return substr($s, 0, $k);
}

// Example usage:
